export type Language = 'ar' | 'fr' | 'en' | 'es' | 'hassaniya';

export interface LanguageOption {
  code: Language;
  badge: string;
  name: string;
  nativeName: string;
  flag: string;
  dir: 'rtl' | 'ltr';
}

