export const translations: Record<Language, Record<string, string>> = {
  ar,
  hassaniya: hass,
  fr,
  en,
  es,
};

// Build reverse lookup map from ANY locale value (ar, hassaniya, fr, en, es) -> translation key
const arExactToKey = new Map<string, string>();
const arCleanToKey = new Map<string, string>();
const anyLocaleExactToKey = new Map<string, string>();

const normalizeArabicKey = (str: string): string =>
  str
    .replace(/^[\s📦💰🚚🏪👥🤝⚙️📋🔍➕➖💸💱🌙☀️🔔⛔⚠️✅✓⏳🔒🔑👑💼📍📞📝👤📊📄🗑️🏷️🧭🌐🇲🇦🇲🇷🇪🇺🇺🇸🇫🇷🇬🇧🇪🇸•:\-–—]+/gu, '')
    .replace(/[\s:：*!؟?.\-–—]+$/gu, '')
    .replace(/\s+/g, ' ')
    .trim();

Object.entries(ar).forEach(([k, v]) => {
  const trimmed = v.trim();
  if (trimmed) {
    arExactToKey.set(trimmed, k);
    anyLocaleExactToKey.set(trimmed, k);
    const cleaned = normalizeArabicKey(trimmed);
    if (cleaned && !arCleanToKey.has(cleaned)) {
      arCleanToKey.set(cleaned, k);
    }
  }
});

// Also index hass.json, fr.json, en.json, es.json so switching from Hassaniya or any language maps back to canonical key!
[hass, fr, en, es].forEach((dict) => {
  Object.entries(dict).forEach(([k, v]) => {
    const trimmed = String(v || '').trim();
    if (trimmed) {
      if (!anyLocaleExactToKey.has(trimmed)) {
        anyLocaleExactToKey.set(trimmed, k);
      }
      if (!arExactToKey.has(trimmed)) {
        arExactToKey.set(trimmed, k);
      }
      const cleaned = normalizeArabicKey(trimmed);
      if (cleaned && !arCleanToKey.has(cleaned)) {
        arCleanToKey.set(cleaned, k);
      }
    }
  });
});

