// Build combined phrase list including both Arabic and Hassaniya phrases
const EXPANDED_PHRASES: Array<[string, MultiLangEntry & { ar: string }]> = [];
for (const [arPhrase, entry] of PHRASE_DICTIONARY) {
  const fullEntry = { ...entry, ar: arPhrase };
  EXPANDED_PHRASES.push([arPhrase, fullEntry]);
  if (entry.hassaniya && entry.hassaniya !== arPhrase) {
    EXPANDED_PHRASES.push([entry.hassaniya, fullEntry]);
  }
}

// Sort phrases longest first so longer expressions match before sub-phrases
const SORTED_PHRASES = EXPANDED_PHRASES.sort((a, b) => b[0].length - a[0].length);
const WORD_MAP = new Map<string, MultiLangEntry & { ar: string }>();
for (const [w, entry] of WORD_DICTIONARY) {
  const fullEntry = { ...entry, ar: w };
  WORD_MAP.set(w, fullEntry);
  if (entry.hassaniya && entry.hassaniya !== w && !WORD_MAP.has(entry.hassaniya)) {
    WORD_MAP.set(entry.hassaniya, fullEntry);
  }
}
for (const [hw, entry] of HASSANIYA_EXTRA_WORDS) {
  WORD_MAP.set(hw, entry);
}

// Match actual Arabic/Hassaniya letters (including گ ڤ چ پ etc.)
const ARABIC_CHAR_REGEX = /[\u0621-\u065F\u0670-\u06D3\u06FA-\u06FC\u0750-\u077F]/;
const ARABIC_WORD_TOKEN_REGEX = /[\u0621-\u065F\u0670-\u06D3\u06FA-\u06FC\u0750-\u077F]+/g;

// Automatic phonetic Arabic-to-Latin transliterator for any custom user-entered Arabic name/word when in FR/EN/ES
const ARABIC_CHAR_TO_LATIN_MAP: Record<string, string> = {
  'ا': 'a', 'أ': 'a', 'إ': 'i', 'آ': 'a', 'ء': '', 'ئ': 'i', 'ؤ': 'ou',
  'ب': 'b', 'ت': 't', 'ث': 'th', 'ج': 'j', 'ح': 'h', 'خ': 'kh',
  'د': 'd', 'ذ': 'dh', 'ر': 'r', 'ز': 'z', 'س': 's', 'ش': 'ch',
  'ص': 's', 'ض': 'd', 'ط': 't', 'ظ': 'z', 'ع': 'a', 'غ': 'gh',
  'ف': 'f', 'ق': 'q', 'ك': 'k', 'گ': 'g', 'ل': 'l', 'م': 'm',
  'ن': 'n', 'ه': 'h', 'ة': 'a', 'و': 'ou', 'ي': 'i', 'ى': 'a',
  'پ': 'p', 'چ': 'ch', 'ڤ': 'v',
  '\u064E': 'a', '\u064F': 'u', '\u0650': 'i', '\u0651': '', '\u0652': '',
};

function transliterateArabicToLatin(token: string): string {
  if (!token) return token;
  let working = token;
  let prefix = '';
  if (working.startsWith('ال') && working.length > 3) {
    prefix = 'El ';
    working = working.slice(2);
  }
  let out = '';
  for (let i = 0; i < working.length; i++) {
    const ch = working[i];
    const mapped = ARABIC_CHAR_TO_LATIN_MAP[ch];
    if (mapped !== undefined) {
      // Improve natural vowel flow for common patterns (e.g., consonant clusters)
      if (
        i === 0 &&
        mapped &&
        !/^[aeiou]/i.test(mapped) &&
        working.length >= 3 &&
        working[1] &&
        !/[اويىأإآ]/.test(working[1])
      ) {
        out += mapped + 'a';
      } else {
        out += mapped;
      }
    } else if (!ARABIC_CHAR_REGEX.test(ch)) {
      out += ch;
    }
  }
  if (!out) return token;
  const capitalized = out.charAt(0).toUpperCase() + out.slice(1);
  return prefix + capitalized;
}

function lookupArabicWordToken(token: string, lang: Language): string | null {
  const resolveEntry = (entry: MultiLangEntry & { ar: string }): string => {
    if (lang === 'ar') return entry.ar || token;
    if (lang === 'hassaniya') return entry.hassaniya ?? token;
    return entry[lang as 'fr' | 'en' | 'es'];
  };

  const direct = WORD_MAP.get(token);
  if (direct) return resolveEntry(direct);

  // Check common Arabic prefixes (ال, و, وال, بال, لل, ل, ف, ب) without breaking words mid-stem
  const prefixes: Array<{ ar: string; fr: string; en: string; es: string }> = [
    { ar: 'وال', fr: 'et ', en: 'and ', es: 'y ' },
    { ar: 'بال', fr: 'en ', en: 'in ', es: 'en ' },
    { ar: 'لل', fr: 'pour ', en: 'for ', es: 'para ' },
    { ar: 'فال', fr: 'dans ', en: 'in ', es: 'en ' },
    { ar: 'كال', fr: 'comme ', en: 'like ', es: 'como ' },
    { ar: 'ال', fr: '', en: '', es: '' },
    { ar: 'و', fr: 'et ', en: 'and ', es: 'y ' },
    { ar: 'ل', fr: 'pour ', en: 'for ', es: 'para ' },
    { ar: 'ب', fr: 'en ', en: 'in ', es: 'en ' },
    { ar: 'ف', fr: 'dans ', en: 'in ', es: 'en ' },
  ];

  // Common possessive/plural/dual/feminine suffixes (including Taa Marbuta -> ت before suffix)
  const suffixes = [
    'تكم', 'تهم', 'تنا', 'تها', 'تين', 'تان', 'تك', 'ته', 'تي', 'ات',
    'كم', 'هم', 'نا', 'ها', 'ين', 'ون', 'ان', 'ك', 'ه', 'ي', 'ة', 'اً', 'ا'
  ];

  const findStemWithSuffix = (stem: string): (MultiLangEntry & { ar: string }) | undefined => {
    for (const sfx of suffixes) {
      if (stem.endsWith(sfx) && stem.length > sfx.length + 1) {
        const base = stem.slice(0, -sfx.length);
        const found =
          WORD_MAP.get(base) ||
          WORD_MAP.get(base + 'ة') ||
          WORD_MAP.get('ال' + base) ||
          WORD_MAP.get('ال' + base + 'ة');
        if (found) return found;
      }
    }
    return undefined;
  };

  for (const p of prefixes) {
    if (token.startsWith(p.ar) && token.length > p.ar.length + 1) {
      const stem = token.slice(p.ar.length);
      const stemEntry = WORD_MAP.get(stem) || WORD_MAP.get('ال' + stem) || findStemWithSuffix(stem);
      if (stemEntry) {
        if (lang === 'hassaniya' || lang === 'ar') return resolveEntry(stemEntry);
        const prefixText = p[lang as 'fr' | 'en' | 'es'];
        return prefixText + resolveEntry(stemEntry);
      }
    }
  }

  const baseEntry = findStemWithSuffix(token);
  if (baseEntry) {
    return resolveEntry(baseEntry);
  }

  return null;
}

const SINGLE_EMOJI_UNIT_REGEX =
  /(?:[\u{1F1E6}-\u{1F1FF}]{2}|[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}\u{2795}\u{2796}][\u{FE0F}\u{20E3}]?)/gu;

export function dedupeRepeatedEmojis(input: string): string {
  if (!input) return input;
  // Collapse any identical consecutive emoji separated only by whitespace (e.g. "⚙️ ⚙️" -> "⚙️")
  return input.replace(
    /((?:[\u{1F1E6}-\u{1F1FF}]{2}|[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{2300}-\u{23FF}\u{2B00}-\u{2BFF}\u{2795}\u{2796}][\u{FE0F}\u{20E3}]?))(?:\s*\1)+/gu,
    '$1'
  );
}

export function translateArabicText(rawText: string, lang: Language): string {
  if (!rawText) return rawText;

  const trimmed = rawText.trim();
  const langDict = translations[lang] || translations.ar;

  // 1. Direct match in any locale JSON -> translations[lang]
  const exactKey = arExactToKey.get(trimmed) || anyLocaleExactToKey.get(trimmed);
  if (exactKey && langDict[exactKey]) {
    return dedupeRepeatedEmojis(rawText.replace(trimmed, langDict[exactKey]));
  }

  // 2. Normalized match (ignoring leading emojis/symbols)
  const cleaned = normalizeArabicKey(trimmed);
  if (cleaned) {
    const cleanKey = arCleanToKey.get(cleaned);
    if (cleanKey && langDict[cleanKey]) {
      const idx = rawText.indexOf(cleaned);
      if (idx !== -1) {
        return dedupeRepeatedEmojis(
          rawText.slice(0, idx) + langDict[cleanKey] + rawText.slice(idx + cleaned.length)
        );
      }
      return dedupeRepeatedEmojis(langDict[cleanKey]);
    }
  }

  if (!ARABIC_CHAR_REGEX.test(rawText)) return dedupeRepeatedEmojis(rawText);

  // 3. Phrase dictionary replacement (handles both Arabic and Hassaniya phrases -> target language)
  let result = rawText;
  for (const [srcPhrase, targetMap] of SORTED_PHRASES) {
    if (result.includes(srcPhrase)) {
      const replacement =
        lang === 'ar'
          ? targetMap.ar
          : lang === 'hassaniya'
          ? targetMap.hassaniya || targetMap.ar
          : targetMap[lang as 'fr' | 'en' | 'es'];
      if (replacement && replacement !== srcPhrase) {
        result = result.split(srcPhrase).join(replacement);
      }
    }
  }

  // Convert Arabic punctuation when translating to Latin languages
  if (lang === 'fr' || lang === 'en' || lang === 'es') {
    result = result.replace(/،/g, ',').replace(/؛/g, ';').replace(/؟/g, '?');
  }

  if (!ARABIC_CHAR_REGEX.test(result)) {
    return dedupeRepeatedEmojis(result);
  }

  // 4. Whole-token word replacement (handles both Arabic and Hassaniya words -> target language, with Latin transliteration fallback for FR/EN/ES)
  result = result.replace(ARABIC_WORD_TOKEN_REGEX, (token) => {
    const translated = lookupArabicWordToken(token, lang);
    if (translated !== null) return translated;
    if (lang === 'fr' || lang === 'en' || lang === 'es') {
      return transliterateArabicToLatin(token);
    }
    return token;
  });

  return dedupeRepeatedEmojis(result);
}

export function getTranslation(lang: Language, key: string, fallback?: string): string {
  const langDict = translations[lang] || translations.ar;
  if (langDict[key]) {
    return dedupeRepeatedEmojis(langDict[key]);
  }
  const baseText = translations.ar[key] || fallback || key;
  return dedupeRepeatedEmojis(translateArabicText(baseText, lang));
}

// WeakMaps for lossless multi-language DOM synchronization across all views & modals
const originalNodeTextMap = new WeakMap<Node, string>();
const lastRenderedNodeTextMap = new WeakMap<Node, string>();
const originalAttrMap = new WeakMap<Element, Record<string, string>>();
const lastRenderedAttrMap = new WeakMap<Element, Record<string, string>>();

const TRANSLATABLE_ATTRS = ['placeholder', 'title', 'aria-label'] as const;

let isApplyingDomLocalization = false;

export function applyDomLocalization(root: ParentNode, lang: Language): void {
  if (isApplyingDomLocalization || !root) return;
  isApplyingDomLocalization = true;

  try {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;
        const tag = parent.tagName;
        if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'NOSCRIPT') {
          return NodeFilter.FILTER_REJECT;
        }
        if (parent.closest('[data-no-translate="true"]')) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      },
    });

    const textNodes: Text[] = [];
    let current = walker.nextNode();
    while (current) {
      textNodes.push(current as Text);
      current = walker.nextNode();
    }

    for (const textNode of textNodes) {
      const currentVal = textNode.nodeValue || '';
      const lastRendered = lastRenderedNodeTextMap.get(textNode);

      // If React updated this node with new source text, normalize to canonical Arabic so switching between ANY two languages is 100% lossless
      if (lastRendered === undefined || currentVal !== lastRendered) {
        const trimmedCur = currentVal.trim();
        const exactMatchKey = anyLocaleExactToKey.get(trimmedCur);
        if (exactMatchKey && translations.ar[exactMatchKey]) {
          const canonicalAr = currentVal.replace(trimmedCur, translations.ar[exactMatchKey]);
          originalNodeTextMap.set(textNode, dedupeRepeatedEmojis(canonicalAr));
        } else if (ARABIC_CHAR_REGEX.test(currentVal)) {
          originalNodeTextMap.set(textNode, dedupeRepeatedEmojis(translateArabicText(currentVal, 'ar')));
        } else {
          originalNodeTextMap.set(textNode, dedupeRepeatedEmojis(currentVal));
        }
      }

      const sourceArabic = originalNodeTextMap.get(textNode) ?? currentVal;
      let targetVal = dedupeRepeatedEmojis(translateArabicText(sourceArabic, lang));

      // Also check if previousSibling text node already ends with the same emoji that targetVal starts with
      const prevSibling = textNode.previousSibling;
      if (prevSibling && prevSibling.nodeType === Node.TEXT_NODE) {
        const prevText = (prevSibling.nodeValue || '').trim();
        const prevEmojis = prevText.match(SINGLE_EMOJI_UNIT_REGEX);
        if (prevEmojis && prevEmojis.length > 0) {
          const lastPrevEmoji = prevEmojis[prevEmojis.length - 1];
          if (prevText.endsWith(lastPrevEmoji)) {
            const trimmedTarget = targetVal.trimStart();
            if (trimmedTarget.startsWith(lastPrevEmoji)) {
              targetVal = trimmedTarget.slice(lastPrevEmoji.length).replace(/^\s+/, '');
            }
          }
        }
      }

      if (textNode.nodeValue !== targetVal) {
        textNode.nodeValue = targetVal;
      }
      lastRenderedNodeTextMap.set(textNode, targetVal);
    }

    // Translate attributes (placeholder, title, aria-label)
    if (root instanceof Element || root instanceof Document) {
      const elements = root.querySelectorAll<HTMLElement>('[placeholder], [title], [aria-label]');
      elements.forEach((el) => {
        if (el.closest('[data-no-translate="true"]')) return;

        let origAttrs = originalAttrMap.get(el);
        if (!origAttrs) {
          origAttrs = {};
          originalAttrMap.set(el, origAttrs);
        }
        let lastAttrs = lastRenderedAttrMap.get(el);
        if (!lastAttrs) {
          lastAttrs = {};
          lastRenderedAttrMap.set(el, lastAttrs);
        }

        for (const attr of TRANSLATABLE_ATTRS) {
          const val = el.getAttribute(attr);
          if (!val) continue;

          if (lastAttrs[attr] === undefined || val !== lastAttrs[attr]) {
            const trimmedVal = val.trim();
            const exactAttrKey = anyLocaleExactToKey.get(trimmedVal);
            if (exactAttrKey && translations.ar[exactAttrKey]) {
              origAttrs[attr] = dedupeRepeatedEmojis(val.replace(trimmedVal, translations.ar[exactAttrKey]));
            } else if (ARABIC_CHAR_REGEX.test(val)) {
              origAttrs[attr] = dedupeRepeatedEmojis(translateArabicText(val, 'ar'));
            } else {
              origAttrs[attr] = dedupeRepeatedEmojis(val);
            }
          }

          const sourceVal = origAttrs[attr] ?? val;
          const translatedVal = dedupeRepeatedEmojis(translateArabicText(sourceVal, lang));
          if (val !== translatedVal) {
            el.setAttribute(attr, translatedVal);
          }
          lastAttrs[attr] = translatedVal;
        }
      });
    }
  } finally {
    isApplyingDomLocalization = false;
  }
}

export function getSavedLanguage(): Language {
  try {
    const saved = (localStorage.getItem('app_lang') || localStorage.getItem('sahara_app_lang')) as Language;
    if (saved && SUPPORTED_LANGUAGES.some(l => l.code === saved)) {
      return saved;
    }
  } catch {}
  return 'ar';
}

export function saveLanguage(lang: Language): void {
  try {
    localStorage.setItem('app_lang', lang);
    localStorage.setItem('sahara_app_lang', lang);
    const isLtr = lang === 'fr' || lang === 'en' || lang === 'es';
    document.documentElement.dir = isLtr ? 'ltr' : 'rtl';
    document.documentElement.lang = lang;
  } catch {}
}
